# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

# Request rebuilding and repeat delivery are checked in
# spec/services/invoices/outbox_delivery_spec.rb; this spec checks only what
# the job itself decides: its queue and where the adapter comes from.
RSpec.describe DeliverInvoiceOperationJob do
  def deliver_job_outbox_row(company_id:, kind:, intent_state:)
    operation_id = SecureRandom.uuid
    InvoiceOperationIntent.create!(
      company_id:, invoice_id: 10, operation_id:, state: intent_state,
      generation: 1, disposition: "active", desired_entry_ids: [3]
    )
    InvoiceOperationOutboxItem.create!(
      company_id:, invoice_id: 10, operation_id:, kind:,
      payload: {
        "company_id" => company_id, "invoice_id" => 10, "operation_id" => operation_id,
        "generation" => 1, "disposition" => "active", "desired_entry_ids" => [3]
      }
    )
  end

  it "runs on the invoice_operations queue" do
    expect(described_class.queue_name).to eq("invoice_operations")
  end

  it "hands the row to the adapter given through reservations:" do
    row = deliver_job_outbox_row(company_id: 7, kind: "commit", intent_state: "committed")
    settled = Invoices::ReservationOutcome.new(state: "committed", conflicts: [], counts: {})
    adapter = RecordingReservationAdapter.new(prepare: settled, commit: settled, abort: settled)

    described_class.perform_now(row.id, reservations: adapter)

    expect(adapter.requests.size).to eq(1)
    expect(row.reload.delivered_at).to be_present
  end

  # "Until later issues register their adapters, every owner maps to a retryable \"adapter not available\" error."
  # "It calls the adapter's `commit` or `abort`, sets `delivered_at` only on a settled outcome, and otherwise keeps the row and increments `attempts`."
  it "counts an attempt and keeps the row when no adapter is registered for the current owner" do
    # The legacy owner has an adapter; the prepared store does not have one yet.
    TimekeepingOwnership.current.update_columns(monolith_store: "prepared")
    row = deliver_job_outbox_row(company_id: 8, kind: "abort", intent_state: "failed")

    expect { described_class.perform_now(row.id) }.not_to raise_error

    expect(row.reload.delivered_at).to be_nil
    expect(row.attempts).to eq(1)
  end
end
